export function getIngestedPage(slug: string): IngestedPage | undefined {
  return INGESTED_PAGES.find((p) => p.slug === slug);
}

export const HTML_REPORT_SLUGS = INGESTED_PAGES.filter((p) => p.kind === "html").map(
  (p) => p.slug,
);

export const MARKDOWN_ARCHIVE_SLUGS = INGESTED_PAGES.filter(
  (p) => p.kind === "markdown",
).map((p) => p.slug);
